35	func (r *TraceReader) GetTraces(ctx context.Context, traceIDs ...tracestore.GetTraceParams) iter.Seq2[[]ptrace.Traces, error] {
36		return func(yield func([]ptrace.Traces, error) bool) {
37			for _, id := range traceIDs {
38				// pcommon.TraceID and cassdbmodel.TraceID are both [16]byte with same byte layout
39				spans, err := r.reader.GetTrace(ctx, cassdbmodel.TraceID(id.TraceID))
40				if err != nil {
41					yield(nil, err)
42					return
43				}
44				if len(spans) == 0 {
45					continue
46				}
47				td := FromDBModel(spans)
48				if !yield([]ptrace.Traces{td}, nil) {
49					return
50				}
51			}
52		}
53	}
54	
55	func (r *TraceReader) FindTraces(ctx context.Context, query tracestore.TraceQueryParams) iter.Seq2[[]ptrace.Traces, error] {
56		return func(yield func([]ptrace.Traces, error) bool) {
57			for trace, err := range r.reader.FindTraces(ctx, v1adapter.GetV1QueryParameters(query)) {
58				if err != nil {
59					yield(nil, err)
60					return
61				}
62				td := FromDBModel(trace.Spans)
63				if !yield([]ptrace.Traces{td}, nil) {
64					return
65				}
66			}
67		}
68	}
69	
70	func (r *TraceReader) FindTraceIDs(ctx context.Context, query tracestore.TraceQueryParams) iter.Seq2[[]tracestore.FoundTraceID, error] {
71		return func(yield func([]tracestore.FoundTraceID, error) bool) {
72			dbIDs, err := r.reader.FindTraceIDs(ctx, v1adapter.GetV1QueryParameters(query))
73			if err != nil {
74				yield(nil, err)
75				return
76			}
77			if len(dbIDs) == 0 {
78				return
79			}
80			otelIDs := make([]tracestore.FoundTraceID, 0, len(dbIDs))
81			for _, id := range dbIDs {
82				otelIDs = append(otelIDs, tracestore.FoundTraceID{
83					TraceID: pcommon.TraceID(id),
84				})
85			}
86			yield(otelIDs, nil)
87		}
